/// The OpenSSL name of the suite `id`, or `None` when OpenSSL does not know it.
#[must_use]
pub fn openssl_cipher_name_by_id(id: u16) -> Option<&'static str> {
    NAMES.binary_search_by_key(&id, |&(k, _)| k).ok().map(|i| NAMES[i].1)
}

#[cfg(test)]
mod tests {
    use super::openssl_cipher_name_by_id as n;

    #[test]
    fn measured_rows() {
        // Measured with OpenSSL 3.5.9 (`openssl ciphers -V 'ALL:COMPLEMENTOFALL'`).
        assert_eq!(n(0x1301), Some("TLS_AES_128_GCM_SHA256"));
        assert_eq!(n(0x1302), Some("TLS_AES_256_GCM_SHA384"));
        assert_eq!(n(0x1303), Some("TLS_CHACHA20_POLY1305_SHA256"));
        assert_eq!(n(0xc02b), Some("ECDHE-ECDSA-AES128-GCM-SHA256"));
        assert_eq!(n(0xc02f), Some("ECDHE-RSA-AES128-GCM-SHA256"));
        assert_eq!(n(0xcca9), Some("ECDHE-ECDSA-CHACHA20-POLY1305"));
        assert_eq!(n(0xcca8), Some("ECDHE-RSA-CHACHA20-POLY1305"));
        assert_eq!(n(0x009c), Some("AES128-GCM-SHA256"));
        // 3DES (0x000a) is not compiled into this OpenSSL; AES128-SHA is the legacy row.
        assert_eq!(n(0x002f), Some("AES128-SHA"));
        assert_eq!(n(0x000a), None);
        assert_eq!(n(0x1305), Some("TLS_AES_128_CCM_8_SHA256")); // only offered with -ciphersuites; HAProxy names it
        assert_eq!(n(0x0a0a), None); // GREASE
        assert_eq!(n(0x00ff), None); // TLS_EMPTY_RENEGOTIATION_INFO_SCSV
        assert_eq!(n(0x5600), None); // TLS_FALLBACK_SCSV
    }

    #[test]
    fn regenerating_gives_the_committed_file() {
        let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../..");
        let script = root.join("tools/gen_cipher_names.py");
        let out = std::process::Command::new("python3")
            .arg("-I")
            .arg(&script)
            .arg("--stdout")
            .output()
            .expect("python3 is needed to check the cipher table");
        assert!(out.status.success(), "generator failed: {}", String::from_utf8_lossy(&out.stderr));
        let committed = std::fs::read_to_string(root.join("crates/ibex-tls/src/cipher_names.rs")).unwrap();
        // The header names the OpenSSL that generated the table; the rows are what is compared.
        let rows = |s: &str| s.lines().filter(|l| !l.contains("Generated with:")).collect::<Vec<_>>().join("\n");
        let fresh = String::from_utf8(out.stdout).unwrap();
        assert_eq!(rows(&fresh), rows(&committed), "cipher_names.rs is stale: rerun tools/gen_cipher_names.py");
    }
}
